10	// userChatAnalysisInterfaceHandle 用户浏览记录查询 API
11	func userChatAnalysisInterfaceHandle(w http.ResponseWriter, r *http.Request) {
12		w.Header().Set("Content-Type", "application/json")
13		setNoCacheHeaders(w)
14	
15		if r.Method != http.MethodPost {
16			json.NewEncoder(w).Encode(ChatAnalysisInterfaceResponse{
17				Success: false,
18				Message: "仅支持 POST 请求",
19			})
20			return
21		}
22	
23		claims := getUserToken(r)
24		if claims.UserID == 0 {
25			json.NewEncoder(w).Encode(ChatAnalysisInterfaceResponse{
26				Success: false,
27				Message: "未登录",
28			})
29			return
30		}
31	
32		var req ChatAnalysisInterfaceRequest
33		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
34			json.NewEncoder(w).Encode(ChatAnalysisInterfaceResponse{
35				Success: false,
36				Message: "无效的请求体: " + err.Error(),
37			})
38			return
39		}
40	
41		// 强制使用 JWT 中的用户名，忽略请求体中的 user_name
42		req.UserName = claims.UserName
43	
44		if req.ModelName == "" {
45			json.NewEncoder(w).Encode(ChatAnalysisInterfaceResponse{
46				Success: false,
47				Message: "缺少 model_name 参数",
48			})
49			return
50		}
51	
52		if err := verifyUserModelAccess(claims, req.ModelName); err != nil {
53			json.NewEncoder(w).Encode(ChatAnalysisInterfaceResponse{
54				Success: false,
55				Message: err.Error(),
56			})
57			return
58		}
59	
60		page := req.Page
61		if page < 1 {
62			page = 1
63		}
64	
65		pageSize := req.PageSize
66		switch pageSize {
67		case 1, 3, 5, 10, 15, 20, 50, 100:
68			// 合法值
69		default:
70			pageSize = 3
71		}
72		days := normalizeChatAnalysisDays(req.Days)
73	
74		logger.Printf("[WEB] UserChatAnalysisInterface user=%s model=%s page=%d size=%d days=%d url=%s method=%s status=%s statusNot=%v tools=%s",
75			req.UserName, req.ModelName, page, pageSize, days, req.FilterURL, req.FilterMethod, req.FilterStatus, req.FilterStatusNot, req.FilterTools)
76	
77		records, total, err := QueryAgentHttpTransactions(
78			req.UserName, req.ModelName, cfg.DBMysqlSubTableNumber, page, pageSize,
79			req.FilterURL, req.FilterMethod, req.FilterStatus, req.FilterStatusNot, req.FilterProtocolType,
80			req.FilterDstModelName, req.FilterTools, req.FilterAgentToolName, days,
81			req.FilterInputTokensNonzero, req.FilterOutputTokensNonzero,
82		)
83		if err != nil {
84			json.NewEncoder(w).Encode(ChatAnalysisInterfaceResponse{
85				Success: false,
86				Message: "查询失败: " + err.Error(),
87			})
88			return
89		}
90	
91		totalPages := int(math.Ceil(float64(total) / float64(pageSize)))
92		if total > 0 && page > totalPages {
93			page = totalPages
94		}
95	
96		result := &AgentHttpQueryResult{
97			Records:     records,
98			TotalCount:  total,
99			TotalPages:  totalPages,
100			CurrentPage: page,
101			PageSize:    pageSize,
102		}
103	
104		json.NewEncoder(w).Encode(ChatAnalysisInterfaceResponse{
105			Success: true,
106			Message: "查询成功",
107			Data:    result,
108		})
109	}
