205	// userChatAnalysisDetailInterfaceHandle 用户端单条记录 body 查询
206	func userChatAnalysisDetailInterfaceHandle(w http.ResponseWriter, r *http.Request) {
207		w.Header().Set("Content-Type", "application/json")
208		setNoCacheHeaders(w)
209	
210		claims := getUserToken(r)
211		if claims.UserID == 0 {
212			json.NewEncoder(w).Encode(ChatAnalysisDetailResponse{
213				Success: false,
214				Message: "未登录",
215			})
216			return
217		}
218	
219		var req ChatAnalysisDetailRequest
220		if r.Method == http.MethodPost {
221			if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
222				json.NewEncoder(w).Encode(ChatAnalysisDetailResponse{
223					Success: false,
224					Message: "无效的请求体: " + err.Error(),
225				})
226				return
227			}
228		} else if r.Method == http.MethodGet {
229			idStr := r.URL.Query().Get("id")
230			if idStr != "" {
231				id, err := strconv.ParseUint(idStr, 10, 64)
232				if err == nil {
233					req.ID = id
234				}
235			}
236			req.ModelName = r.URL.Query().Get("model_name")
237		} else {
238			json.NewEncoder(w).Encode(ChatAnalysisDetailResponse{
239				Success: false,
240				Message: "仅支持 POST 或 GET 请求",
241			})
242			return
243		}
244	
245		req.UserName = claims.UserName
246	
247		if req.ModelName == "" || req.ID == 0 {
248			json.NewEncoder(w).Encode(ChatAnalysisDetailResponse{
249				Success: false,
250				Message: "缺少必要参数",
251			})
252			return
253		}
254	
255		if err := verifyUserModelAccess(claims, req.ModelName); err != nil {
256			json.NewEncoder(w).Encode(ChatAnalysisDetailResponse{
257				Success: false,
258				Message: err.Error(),
259			})
260			return
261		}
262	
263		reqHeaders, respHeaders, reqBody, respBody, err := GetAgentHttpTransactionDetailByID(
264			req.UserName, req.ModelName, cfg.DBMysqlSubTableNumber, req.ID,
265		)
266		if err != nil {
267			json.NewEncoder(w).Encode(ChatAnalysisDetailResponse{
268				Success: false,
269				Message: "查询失败: " + err.Error(),
270			})
271			return
272		}
273	
274		json.NewEncoder(w).Encode(ChatAnalysisDetailResponse{
275			Success:         true,
276			Message:         "查询成功",
277			RequestHeaders:  reqHeaders,
278			ResponseHeaders: respHeaders,
279			RequestBody:     reqBody,
280			ResponseBody:    respBody,
281		})
282	}
