267	    function formatSize(bytes) {
268	        if (bytes < 0) return '0 B';
269	        if (bytes < 1024) return bytes + ' B';
270	        if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(2) + ' KB';
271	        if (bytes < 1024 * 1024 * 1024) return (bytes / (1024 * 1024)).toFixed(2) + ' MB';
272	        return (bytes / (1024 * 1024 * 1024)).toFixed(2) + ' GB';
273	    }
274	    function formatTime(isoString) {
275	        if (!isoString) return '';
276	        var d = new Date(isoString);
277	        if (isNaN(d.getTime())) return isoString;
278	        var pad = function(n) { return n < 10 ? '0' + n : n; };
279	        return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()) + ' ' +
280	               pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':' + pad(d.getSeconds());
281	    }
282	    function decodeBody(encoded) {
283	        if (!encoded) return '';
