287	            for (var i = 0; i < binary.length; i++) {
288	                bytes[i] = binary.charCodeAt(i);
289	            }
290	            return new TextDecoder('utf-8').decode(bytes);
291	        } catch(e) {
292	            return encoded;
293	        }
294	    }
