298	            var arr = [];
299	            for (var i = 1; i <= total; i++) arr.push(i);
300	            return arr;
301	        }
302	        var pages = [];
303	        // 始终显示第一页
304	        pages.push(1);
305	        // 计算中间窗口: 当前页前后各1页，共3页
306	        var start = Math.max(2, current - 1);
307	        var end = Math.min(total - 1, current + 1);
308	        // 如果窗口太小，尽量扩展到3页
309	        if (end - start + 1 < 3) {
310	            if (start === 2) {
311	                end = Math.min(total - 1, 4);
312	            } else if (end === total - 1) {
313	                start = Math.max(2, total - 3);
314	            }
315	        }
316	        // 左侧省略号
317	        if (start > 2) {
318	            pages.push(-1);
319	        } else if (start === 2) {
320	            // 不显示省略号，直接显示第2页
321	        }
322	        // 中间页码
323	        for (var i = start; i <= end; i++) {
324	            pages.push(i);
325	        }
326	        // 右侧省略号
327	        if (end < total - 1) {
328	            pages.push(-1);
329	        }
330	        // 始终显示最后一页
331	        pages.push(total);
332	        return pages;
333	    }
