351	    function parseToolsFilter(value) {
352	        var text = (value || '').trim();
353	        if (!text) return {ok: true, tools: []};
354	        if (text.charAt(0) !== '[' || text.charAt(text.length - 1) !== ']') {
355	            return {ok: false, message: "工具列表格式错误，请使用数组格式，例如 ['Agent','AskUserQuestion','Bash']"};
356	        }
357	        var tools = [];
358	        var i = 1;
359	        var end = text.length - 1;
360	        while (i < end) {
361	            while (i < end && /\s/.test(text.charAt(i))) i++;
362	            if (i >= end) break;
363	            var quote = text.charAt(i);
364	            if (quote !== "'" && quote !== '"') {
365	                return {ok: false, message: '工具名称必须使用单引号或双引号包裹'};
366	            }
367	            i++;
368	            var valueChars = [];
369	            while (i < end) {
370	                var ch = text.charAt(i);
371	                if (ch === '\\') {
372	                    if (i + 1 >= end) {
373	                        return {ok: false, message: '工具名称转义字符不完整'};
374	                    }
375	                    valueChars.push(text.charAt(i + 1));
376	                    i += 2;
377	                    continue;
378	                }
379	                if (ch === quote) break;
380	                valueChars.push(ch);
381	                i++;
382	            }
383	            if (i >= end || text.charAt(i) !== quote) {
384	                return {ok: false, message: '工具名称缺少结束引号'};
385	            }
386	            i++;
387	            var toolName = valueChars.join('').trim();
388	            if (!toolName) {
389	                return {ok: false, message: '工具名称不能为空'};
390	            }
391	            tools.push(toolName);
392	            while (i < end && /\s/.test(text.charAt(i))) i++;
393	            if (i >= end) break;
394	            if (text.charAt(i) !== ',') {
395	                return {ok: false, message: '多个工具名称之间需要使用英文逗号分隔'};
396	            }
397	            i++;
398	            while (i < end && /\s/.test(text.charAt(i))) i++;
399	            if (i >= end) {
400	                return {ok: false, message: '工具列表末尾不能带多余逗号'};
401	            }
402	        }
403	        return {ok: true, tools: tools};
404	    }
